INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT139-S1-Q10$batch11$, 139, 1, 10, $batch11$Must Be True$batch11$, $batch11$Large deposits of the rare mineral nahcolite formed in salty lakes 50 million to 52 million years ago during the Eocene epoch. Laboratory tests found that, in salty water, nahcolite can form only when the atmosphere contains at least 1,125 parts per million of carbon dioxide.$batch11$, $batch11$The statements above, if true, most strongly support which one of the following?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=139 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$For most of the time since the Eocene epoch, the level of carbon dioxide in the atmosphere has been lower than it was during most of the Eocene epoch.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Levels of carbon dioxide in the atmosphere fluctuated greatly during the Eocene epoch.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Lakes were more likely to be salty during periods when the level of carbon dioxide in the atmosphere was at least 1,125 parts per million.$batch11$, $batch11$Reversed$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$The atmosphere contained at least 1,125 parts per million of carbon dioxide during at least some part of the Eocene epoch.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$No significant deposits of nahcolite have formed at any time since the Eocene epoch.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Large nahcolite deposits formed in salty lakes during the Eocene. In salty water, nahcolite can form only when carbon dioxide is at least 1,125 parts per million.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Nahcolite forming in salty water → carbon dioxide at least 1,125 ppm. It did form, so carbon dioxide reached that level at least while those deposits formed. That's only part of the Eocene, and says nothing about other times.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Carbon dioxide was at least 1,125 ppm during some part of the Eocene.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$We know nothing about carbon dioxide after the Eocene.$batch11$), ($batch11$B$batch11$, $batch11$We know carbon dioxide was high at some point. Nothing says it swung up and down.$batch11$), ($batch11$C$batch11$, $batch11$Carbon dioxide is required for nahcolite in salty water. Nothing says high carbon dioxide made lakes salty.$batch11$), ($batch11$D$batch11$, $batch11$Nahcolite formed, so its requirement was met during at least part of the Eocene.$batch11$), ($batch11$E$batch11$, $batch11$Nahcolite could have formed since then whenever carbon dioxide was high enough.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT139-S1-Q10$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
